
import { keccak256, AbiCoder } from 'ethers';
import { ethers } from 'hardhat';
import 'dotenv/config'

async function main() {

  /* -------------GET THE RELEVANT VALUES----------------- */
  // const factoryStakerAddress = process.env.EXPECTED_PLENTIFI_FACTORY_STAKER_ADDRESS;
  // if (!factoryStakerAddress) throw new Error('EXPECTED_PLENTIFI_FACTORY_STAKER_ADDRESS not set in env');
  // const accountFactoryAddress = process.env.EXPECTED_PLENTIFI_CANONICAL_FACTORY_ADDRESS;
  // if (!accountFactoryAddress) throw new Error('EXPECTED_PLENTIFI_CANONICAL_FACTORY_ADDRESS not set in env');
  // const abiCoder = new AbiCoder();


  // const callData = "";
  const callData = "";

  const abiCoder = new AbiCoder();

  const decoded = abiCoder.decode(
    ['address', 'bytes', 'bytes32'],
    "0x" + callData.slice(10)
  );
  console.log('decoded raw:', decoded);

  // precompute the address
  const AccountFactory = await ethers.getContractAt("PlentiFiAccountFactory", process.env.EXPECTED_PLENTIFI_CANONICAL_FACTORY_ADDRESS);
  const precomputedAccountAddress = await AccountFactory.getAddressWrapper(decoded[1], decoded[2]);

  console.log('precomputedAccountAddress:', precomputedAccountAddress);
  console.log("code at precomputedAccountAddress:", (await ethers.provider.getCode(precomputedAccountAddress)));

  // call 0xaeE832ca4160496bBD35d54d0873cEda9D197a2d with callData
  const tx = await ethers.provider.send('eth_sendTransaction', [{
    // factory staker address
    to: "0x643e1210Dce2aC4B1183e21bBCb2dc6f6AA914D8", // arb sepolia: "0xaeE832ca4160496bBD35d54d0873cEda9D197a2d",
    data: callData
  }]);

  console.log('tx:', tx);

  // display the tx logs
  const receipt = await ethers.provider.getTransactionReceipt(tx);
  console.log('receipt:', JSON.stringify(receipt));

}

main()
  .then(() => process.exit(0))
  .catch((error) => {
    console.error(error);
    process.exit(1);
  });
